    #region Bulk action
    private void ConfirmBulkAction(string type, string value)
    {
        bulkActionType = type;
        bulkActionValue = value;
        showConfirmModal = true;
    }

    private void CancelBulkAction() => showConfirmModal = false;

    private async Task ApplyConfirmedBulkAction()
    {
        showConfirmModal = false;
        if (isKhoaSoDiem || !IsEditMode) return;

        try
        {
            var fields = Array.Empty<string>();

            if (IsKhoi)
            {
                fields = bulkActionType switch
                {
                    "NLC" => new[] { "Tt22xNlTuChuCk", "Tt22xNlGthtCk", "Tt22xNlGqvdCk" },
                    "NLD" => new[] { "Tt22xNlNgonNguCk", "Tt22xNlTinhToanCk", "Tt22xNlKhoaHocCk", "Tt22xNlThamMiCk", "Tt22xNlTheChatCk" },
                    "PC" => new[] { "Tt22xPcYeuNuocCk", "Tt22xPcNhanAiCk", "Tt22xPcChamChiCk", "Tt22xPcTtCk", "Tt22xPcTnCk" },
                    _ => Array.Empty<string>()
                };
            }
            else
            {
                fields = bulkActionType switch
                {
                    "NLC" => new[] { "Tt22xNlTuChuCk", "Tt22xNlGthtCk", "Tt22xNlGqvdCk" },
                    "NLD" => new[]
                    {
                    "Tt22xNlNgonNguCk",
                    "Tt22xNlTinhToanCk",
                    "Tt22xNlKhoaHocCk",
                    "Tt22xNlThamMiCk",
                    "Tt22xNlTheChatCk",
                    "Tt22xNlTinHocCk",
                    "Tt22xNlCongNgheCk"
                },
                    "PC" => new[] { "Tt22xPcYeuNuocCk", "Tt22xPcNhanAiCk", "Tt22xPcChamChiCk", "Tt22xPcTtCk", "Tt22xPcTnCk" },
                    _ => Array.Empty<string>()
                };
            }

            foreach (var hs in hocSinhList)
            {
                var d = GetDanhGia(hs.MaHsSo);
                bool hasChange = false;

                foreach (var f in fields)
                {
                    switch (f)
                    {
                        case "Tt22xNlTuChuCk": if (d.Tt22xNlTuChuCk != bulkActionValue) { d.Tt22xNlTuChuCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlGthtCk": if (d.Tt22xNlGthtCk != bulkActionValue) { d.Tt22xNlGthtCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlGqvdCk": if (d.Tt22xNlGqvdCk != bulkActionValue) { d.Tt22xNlGqvdCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlNgonNguCk": if (d.Tt22xNlNgonNguCk != bulkActionValue) { d.Tt22xNlNgonNguCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlTinhToanCk": if (d.Tt22xNlTinhToanCk != bulkActionValue) { d.Tt22xNlTinhToanCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlKhoaHocCk": if (d.Tt22xNlKhoaHocCk != bulkActionValue) { d.Tt22xNlKhoaHocCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlThamMiCk": if (d.Tt22xNlThamMiCk != bulkActionValue) { d.Tt22xNlThamMiCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlTheChatCk": if (d.Tt22xNlTheChatCk != bulkActionValue) { d.Tt22xNlTheChatCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlTinHocCk": if (d.Tt22xNlTinHocCk != bulkActionValue) { d.Tt22xNlTinHocCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xNlCongNgheCk": if (d.Tt22xNlCongNgheCk != bulkActionValue) { d.Tt22xNlCongNgheCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcYeuNuocCk": if (d.Tt22xPcYeuNuocCk != bulkActionValue) { d.Tt22xPcYeuNuocCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcNhanAiCk": if (d.Tt22xPcNhanAiCk != bulkActionValue) { d.Tt22xPcNhanAiCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcChamChiCk": if (d.Tt22xPcChamChiCk != bulkActionValue) { d.Tt22xPcChamChiCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcTtCk": if (d.Tt22xPcTtCk != bulkActionValue) { d.Tt22xPcTtCk = bulkActionValue; hasChange = true; } break;
                        case "Tt22xPcTnCk": if (d.Tt22xPcTnCk != bulkActionValue) { d.Tt22xPcTnCk = bulkActionValue; hasChange = true; } break;
                    }
                }

                if (hasChange)
                {
                    modifiedStudents.Add(d.MaHocSinhSo);
                }
            }

            ShowToast($"Đã áp dụng '{GetMucDatDuocText(bulkActionValue)}' cho {hocSinhList.Count} học sinh (chưa lưu)", "success");
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
    }
