    #region Nộp điểm lên Sở
    private async Task ShowConfirmNopDiemModal()
    {
        thData.danhSachKhoiList = await TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc);
        thData.danhSachLopList = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, SelectedNamHoc);
        thData.danhSachGiaoVienList = await TruongService.hGetDanhSachGiaoVien(maTruongBo, SelectedNamHoc);
        thData.truong = await TruongService.hThongTinTruongByID(maTruongBo);
        validationResult = ValidateDataBeforeNopSimple();
        if (!validationResult.isValid)
        {
            ShowToast(validationResult.message, "warning");
            return;
        }
        showNopDiemModal = true;
    }

    private void CloseNopDiemModal() => showNopDiemModal = false;

    private (bool isValid, string message, int countValid) ValidateDataBeforeNopSimple()
    {
        if (hocSinhList.Count == 0) return (false, "Không có học sinh", 0);
        int countValid = hocSinhList.Count(HasAnyEvaluation);
        if (countValid == 0) return (false, "Không có học sinh nào có dữ liệu đánh giá", 0);
        return (true, $"Có {countValid}/{hocSinhList.Count} học sinh có dữ liệu", countValid);
    }

    private bool HasAnyEvaluation(HocSinhDTO hs)
    {
        var d = GetDanhGia(hs.MaHsSo);
        return !string.IsNullOrEmpty(d.Tt22xNlTuChuCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlGthtCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlGqvdCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlNgonNguCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlTinhToanCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlKhoaHocCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlThamMiCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlTheChatCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlTinHocCk) ||
               !string.IsNullOrEmpty(d.Tt22xNlCongNgheCk) ||
               !string.IsNullOrEmpty(d.Tt22xPcYeuNuocCk) ||
               !string.IsNullOrEmpty(d.Tt22xPcNhanAiCk) ||
               !string.IsNullOrEmpty(d.Tt22xPcChamChiCk) ||
               !string.IsNullOrEmpty(d.Tt22xPcTtCk) ||
               !string.IsNullOrEmpty(d.Tt22xPcTnCk) ||
               !string.IsNullOrEmpty(d.NxnlCk) ||
               !string.IsNullOrEmpty(d.NxnlDacThuCk) ||
               !string.IsNullOrEmpty(d.NxpcCk);
    }

    private async Task NopDiemLenSo()
    {
        if (!validationResult.isValid) return;

        try
        {
            isNopDiemLoading = true;
            StateHasChanged();

            var hocSinhCoDanhGia = hocSinhList
                .Where(hs => HasAnyEvaluation(hs))
                .Select(hs => new { MaHsSo = hs.MaHsSo })
                .ToList();

            var requestBody = new
            {
                matruongbo = maTruongBo,
                hocky = int.Parse(SelectedHocKy),
                ma_lop = int.Parse(SelectedLop),
                id_nguoi_nop = "", // Cần lấy từ dropdown nếu có
                nam_hoc = int.Parse(SelectedNamHoc.Split('-')[0]),
                nopNLPC = hocSinhCoDanhGia
            };

            string apiUrl = TruongHocData.API_KetNoiSGD + "NopNangLucPhamChatC1";
            using var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromMinutes(5);

            var jsonContent = new StringContent(
                System.Text.Json.JsonSerializer.Serialize(requestBody),
                Encoding.UTF8,
                "application/json"
            );

            var response = await httpClient.PostAsync(apiUrl, jsonContent);

            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadAsStringAsync();
                var result = System.Text.Json.JsonSerializer.Deserialize<ApiResponse_NopDiem>(json);
                if (result?.status_code == 200)
                {
                    ShowToast($"✅ Nộp thành công {hocSinhCoDanhGia.Count} học sinh", "success");
                    isKhoaSoDiem = true;
                    PN_ConfigHelper.UpdateKhoaSoDiem(true);
                    PN_PublicVariables.IsKhoaSoDiem = "true";
                    CloseNopDiemModal();
                }
                else
                {
                    ShowToast($"❌ Lỗi: {result?.message}", "danger");
                }
            }
            else
            {
                ShowToast($"❌ Lỗi kết nối Sở", "danger");
            }
        }
        catch (Exception ex)
        {
            ShowToast("Da xay ra loi, vui long thu lai!", "error");
        }
        finally
        {
            isNopDiemLoading = false;
            StateHasChanged();
        }
    }
